function createBreaker(fn, { failureThreshold = 3, resetTimeoutMs = 10000, now = Date.now } = {}) {
  let failures = 0;
  let openedAt = null; // null = closed
  let probing = false; // มีคำขอทดลองใน half-open ค้างอยู่หรือไม่
  let epoch = 0; // เพิ่มทุกครั้งที่วงจรเปลี่ยนระหว่าง closed กับ open

  function getState() {
    if (openedAt === null) return 'closed';
    return now() - openedAt >= resetTimeoutMs ? 'half-open' : 'open';
  }

  async function call(...args) {
    const state = getState();
    if (state === 'open') throw new Error('circuit open');
    const isProbe = state === 'half-open';
    if (isProbe) {
      if (probing) throw new Error('circuit open');
      probing = true;
    }
    const startEpoch = epoch;
    // เฉพาะคำขอทดลอง หรือคำขอที่เริ่มในรอบ closed ปัจจุบันเท่านั้นที่เปลี่ยนสถานะได้
    const counts = () => isProbe || (startEpoch === epoch && openedAt === null);
    try {
      const result = await fn(...args);
      if (counts()) {
        failures = 0;
        if (openedAt !== null) {
          openedAt = null; // คำขอทดลองสำเร็จ: กลับ closed
          epoch += 1;
        }
      }
      return result;
    } catch (err) {
      if (counts()) {
        failures += 1;
        if (isProbe || failures >= failureThreshold) {
          openedAt = now();
          epoch += 1;
        }
      }
      throw err;
    } finally {
      if (isProbe) probing = false;
    }
  }

  return { call, getState };
}
